  "bbb_prediction": "fail",
  "claims": [
    {
      "card_ids": ["C02"],
      "claim": "The closest analogue (Morgan 0.39), a benzimidazole-piperidine, shows B/Pb 2.7 and is CNS-permeable, but it lacks the query's carboxylic acid and is a monobasic lipophilic amine.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C01"],
      "claim": "A piperidine-linked heteroaromatic amide shows brain Cmax 234 ng/g and free BBB passage in rat, again without an ionizable acid.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C05"],
      "claim": "PET imaging in baboons shows rapid brain uptake for a related benzimidazolone-piperidine, supporting CNS penetration of the core scaffold but not the acid-modified query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "low",
  "decision_summary": "The closest analogues are CNS-permeable, but all lack the query's ionizable carboxylic acid and are only weakly similar (Morgan ≤0.39). The query is a large zwitterion (basic piperidine + carboxylic acid) at physiological pH, analogous to fexofenadine, which is peripherally restricted. This charge state is expected to severely limit passive BBB diffusion and likely engage efflux; no direct evidence covers the acid-bearing scaffold. Therefore, meaningful CNS access is not adequately supported.",
  "evidence_gaps": [
    "No direct brain/CSF/plasma data for the query or any carboxylic acid-containing analogue",
    "Efflux transporter (P-gp/BCRP/OAT3) status unknown",
    "Unbound brain-to-plasma ratio not measured"
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

